import time
from abc import ABC, abstractmethod
from typing import Callable


class RateLimitStrategy(ABC):
    """Strategy interface: decides whether one request for `key` at time `now` is allowed.
    Implementations keep independent state per key."""

    @abstractmethod
    def allow(self, key: str, now: float) -> bool: ...


class TokenBucket(RateLimitStrategy):
    def __init__(self, capacity: int, refill_per_sec: float) -> None:
        """Bucket starts full with `capacity` tokens and refills continuously.
        Raise ValueError if capacity or refill_per_sec is not positive."""
        raise NotImplementedError

    def allow(self, key: str, now: float) -> bool:
        """Refill for elapsed time (capped at capacity), then spend 1 token if available."""
        raise NotImplementedError


class SlidingWindowLog(RateLimitStrategy):
    def __init__(self, limit: int, window_sec: float) -> None:
        """At most `limit` allowed requests in any window of `window_sec` seconds.
        Raise ValueError if limit or window_sec is not positive."""
        raise NotImplementedError

    def allow(self, key: str, now: float) -> bool:
        """Forget timestamps <= now - window_sec; allow (and record) if under the limit.
        Rejected requests are not recorded."""
        raise NotImplementedError


class RateLimiter:
    """Front door: per-user limiting with a pluggable strategy and an injectable clock."""

    def __init__(self, strategy: RateLimitStrategy,
                 clock: Callable[[], float] = time.monotonic) -> None:
        raise NotImplementedError

    def allow(self, user_id: str) -> bool:
        raise NotImplementedError

