from dataclasses import dataclass
from typing import Any, Callable


@dataclass
class Job:
    id: str
    fn: Callable[[], Any]
    priority: int = 0          # higher runs first; ties run in submission order
    max_retries: int = 0       # retries allowed after the first attempt
    attempts: int = 0
    status: str = "queued"     # queued | running | succeeded | failed
    result: Any = None
    last_error: str | None = None


class JobScheduler:
    """Owns the queue. Workers pull from it and report back."""

    def __init__(self, base_delay: float = 1.0) -> None:
        raise NotImplementedError

    def submit(self, job: Job) -> None:
        """Queue a job. Raise ValueError on a duplicate id."""
        raise NotImplementedError

    def pull(self, now: float) -> Job | None:
        """Return the highest-priority job that is ready at `now` (or None).
        Marks it running and increments attempts."""
        raise NotImplementedError

    def complete(self, job_id: str, result: Any) -> None:
        """Mark the job succeeded and store its result."""
        raise NotImplementedError

    def fail(self, job_id: str, error: Exception, now: float) -> None:
        """Record the error. If attempts <= max_retries, re-queue it to become ready at
        now + base_delay * 2 ** (attempts - 1); otherwise mark it failed."""
        raise NotImplementedError

    def get(self, job_id: str) -> Job:
        """Look up a job by id (KeyError if unknown)."""
        raise NotImplementedError


class Worker:
    def __init__(self, scheduler: JobScheduler) -> None:
        raise NotImplementedError

    def run_once(self, now: float) -> bool:
        """Pull one job, run it, report success/failure. Return False if nothing was ready."""
        raise NotImplementedError

