import re
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Iterator


@dataclass(frozen=True)
class Example:
    id: str
    input: str
    expected: str


class Dataset:
    def __init__(self, examples: list[Example]) -> None:
        """Raise ValueError on duplicate example ids."""
        raise NotImplementedError

    @classmethod
    def from_records(cls, records: list[dict]) -> "Dataset":
        """Build from dicts with keys id/input/expected; ValueError if a key is missing."""
        raise NotImplementedError

    def __len__(self) -> int:
        raise NotImplementedError

    def __iter__(self) -> Iterator[Example]:
        raise NotImplementedError


class ModelAdapter(ABC):
    """Anything that turns a prompt into text (a real API client, a fake, a judge)."""

    @abstractmethod
    def generate(self, prompt: str) -> str: ...


# Provided: a deterministic model for tests and your main.
class DictModel(ModelAdapter):
    """Answers from a prompt -> answer dict; raises RuntimeError for prompts containing 'BOOM'."""

    def __init__(self, answers: dict[str, str]) -> None:
        self.answers = answers
        self.prompts: list[str] = []

    def generate(self, prompt: str) -> str:
        self.prompts.append(prompt)
        if "BOOM" in prompt:
            raise RuntimeError("model crashed")
        return self.answers.get(prompt, "")


@dataclass
class Task:
    name: str
    dataset: Dataset
    prompt_template: str = "{input}"

    def build_prompt(self, example: Example) -> str:
        """Fill {input} in prompt_template with the example's input."""
        raise NotImplementedError


class Grader(ABC):
    @abstractmethod
    def grade(self, output: str, example: Example) -> float:
        """Return a score in [0, 1]."""


class ExactMatchGrader(Grader):
    def grade(self, output: str, example: Example) -> float:
        """1.0 if equal after lower-casing and collapsing whitespace, else 0.0."""
        raise NotImplementedError


class RegexGrader(Grader):
    def grade(self, output: str, example: Example) -> float:
        """Treat example.expected as a regex; 1.0 if re.search finds it (case-insensitive)."""
        raise NotImplementedError


class LLMJudgeGrader(Grader):
    def __init__(self, judge: ModelAdapter) -> None:
        raise NotImplementedError

    def grade(self, output: str, example: Example) -> float:
        """Send the judge a prompt containing the input, the expected answer and the output.
        1.0 if its reply starts with PASS (case-insensitive), else 0.0."""
        raise NotImplementedError


@dataclass
class Result:
    example_id: str
    output: str
    score: float
    error: str | None = None


@dataclass
class Report:
    task_name: str
    results: list[Result] = field(default_factory=list)

    @property
    def accuracy(self) -> float:
        """Mean score (0.0 for an empty report)."""
        raise NotImplementedError

    @property
    def n_errors(self) -> int:
        raise NotImplementedError

    def failed_ids(self) -> list[str]:
        """Ids with score < 1.0, in dataset order."""
        raise NotImplementedError


class Runner:
    def __init__(self, model: ModelAdapter, grader: Grader) -> None:
        raise NotImplementedError

    def run(self, task: Task) -> Report:
        """Prompt -> model -> grade for every example. A model exception becomes a Result
        with score 0.0 and error set; the run continues."""
        raise NotImplementedError

