        self.errors = errors


class LLMGateway:
    def __init__(self, routes: list[Route], prices: dict[str, tuple[float, float]]) -> None:
        if not routes:
            raise ValueError("at least one route is required")
        unknown = [r.model for r in routes if r.model not in prices]
        if unknown:
            raise ValueError(f"no price for models {unknown}")
        self.routes = list(routes)
        self.prices = prices
        self.ledger: list[Completion] = []

    def _cost(self, model: str, input_tokens: int, output_tokens: int) -> float:
        p_in, p_out = self.prices[model]
        return input_tokens / 1000 * p_in + output_tokens / 1000 * p_out

    def complete(self, prompt: str) -> Completion:
        errors: list[str] = []
        for route in self.routes:
            try:
                resp = route.provider.complete(prompt, route.model)
            except Exception as error:
                errors.append(f"{route.provider.name}/{route.model}: {type(error).__name__}: {error}")
                continue
            completion = Completion(resp.text, route.provider.name, route.model, resp.input_tokens,
                                    resp.output_tokens, self._cost(route.model, resp.input_tokens, resp.output_tokens))
            self.ledger.append(completion)
            return completion
        raise AllProvidersFailed(errors)

    def total_cost(self) -> float:
        return sum(c.cost_usd for c in self.ledger)
