import string
from dataclasses import dataclass


class PromptInputError(ValueError):
    """Variables passed to render() do not match the template."""


@dataclass(frozen=True)
class PromptTemplate:
    name: str
    version: int
    text: str

    @property
    def variables(self) -> set[str]:
        return {field for _, field, _, _ in string.Formatter().parse(self.text) if field is not None}


@dataclass(frozen=True)
class RenderedPrompt:
    text: str
    name: str
    version: int


def _check_template(text: str) -> None:
    try:
        fields = [f for _, f, _, _ in string.Formatter().parse(text) if f is not None]
    except ValueError as error:
        raise ValueError(f"malformed template: {error}") from error
    for field in fields:
        if not field.isidentifier():
            raise ValueError(f"placeholder {{{field}}} must be a named identifier")


class PromptRegistry:
    def __init__(self) -> None:
        self._templates: dict[str, list[PromptTemplate]] = {}

    def register(self, name: str, text: str) -> PromptTemplate:
        _check_template(text)
        history = self._templates.setdefault(name, [])
        if history and history[-1].text == text:
            return history[-1]
        template = PromptTemplate(name, len(history) + 1, text)
        history.append(template)
        return template

    def get(self, name: str, version: int | None = None) -> PromptTemplate:
        history = self._templates.get(name)
        if not history:
            raise KeyError(f"unknown template {name!r}")
        if version is None:
            return history[-1]
        if not 1 <= version <= len(history):
            raise KeyError(f"{name!r} has no version {version}")
        return history[version - 1]

    def versions(self, name: str) -> list[int]:
        return [t.version for t in self._templates.get(name, [])]

    def render(self, name: str, variables: dict[str, object], version: int | None = None) -> RenderedPrompt:
        template = self.get(name, version)
        expected = template.variables
        missing = sorted(expected - variables.keys())
        extra = sorted(variables.keys() - expected)
        if missing or extra:
            raise PromptInputError(f"{name} v{template.version}: missing {missing}, unexpected {extra}")
        return RenderedPrompt(template.text.format(**variables), name, template.version)
