### Pattern notes
- Interviewers check that each stage is replaceable.
- Patterns: **Factory** (`LoaderFactory` picks loaders), **Strategy** (each stage), pipeline/**Template Method** (fixed stage order).
- NFRs: a new format is one class + one `register`; one bad doc must not stop a batch; batch the embedding calls.
- Follow-up answers: incremental re-index via a content hash per doc, delete-then-add its chunks; failures in a batch are reported, retried, then dead-lettered.
- Learn from: [Factory Method](https://refactoring.guru/design-patterns/factory-method), [Strategy](https://refactoring.guru/design-patterns/strategy), [Template Method](https://refactoring.guru/design-patterns/template-method)

### Key insight
A pipeline of interfaces: the orchestrator knows only `Loader -> Chunker -> Embedder -> VectorStore`. Formats are open for extension via a Factory registry, and every other stage is a Strategy you can swap for tests or upgrades.

### Approach
1. Loaders normalise raw input into `Document` with source/format metadata.
2. `LoaderFactory` maps extensions to loader classes; `register` adds formats without editing code.
3. `FixedSizeChunker` slides a word window (`step = size - overlap`) and stops at the window that reaches the end.
4. `InMemoryVectorStore` keeps `(chunk, vector)` pairs and ranks by cosine.
5. `IngestionPipeline.ingest` composes the stages and embeds all chunks of a document in one batch call.

### Complexity
Chunking O(words). Search O(N * dim) brute force (an ANN index such as HNSW in production).

### Common mistakes
- `if ext == ".pdf": ... elif ...` chains inside the pipeline instead of a factory.
- Chunk loops that emit a trailing chunk made only of overlap words, or loop forever when `overlap >= size`.
- Losing document metadata on chunks (breaks filters and citations).
- One embed call per chunk (slow and expensive).

### Talking points
Incremental re-index: store a content hash per `doc_id`; on change delete its chunks and re-ingest. Metadata filters: filter candidates before ranking. Failure handling: `ingest_many` returns `{ok, failed: {id: error}}` so one bad file does not abort the batch.

```python
import hashlib
import html
import math
import re
from abc import ABC, abstractmethod
from dataclasses import dataclass, field


@dataclass
class Document:
    id: str
    text: str
    metadata: dict = field(default_factory=dict)


@dataclass
class Chunk:
    doc_id: str
    index: int
    text: str
    metadata: dict = field(default_factory=dict)


class UnsupportedFormat(ValueError):
    """No loader is registered for the source's extension."""


class Loader(ABC):
    @abstractmethod
    def load(self, source_id: str, raw: str) -> Document: ...


class Chunker(ABC):
    @abstractmethod
    def chunk(self, doc: Document) -> list[Chunk]: ...


class Embedder(ABC):
    @abstractmethod
    def embed(self, texts: list[str]) -> list[list[float]]: ...


class VectorStore(ABC):
    @abstractmethod
    def add(self, chunks: list[Chunk], vectors: list[list[float]]) -> None: ...

    @abstractmethod
    def search(self, vector: list[float], k: int) -> list[Chunk]: ...

    @abstractmethod
    def __len__(self) -> int: ...


# Provided: deterministic bag-of-words hashing embedder (stand-in for a real model).
class HashEmbedder(Embedder):
    def __init__(self, dim: int = 64) -> None:
        self.dim = dim

    def embed(self, texts: list[str]) -> list[list[float]]:
        vectors = []
        for text in texts:
            vec = [0.0] * self.dim
            for word in re.findall(r"[a-z0-9]+", text.lower()):
                vec[int(hashlib.md5(word.encode()).hexdigest(), 16) % self.dim] += 1.0
            norm = math.sqrt(sum(v * v for v in vec)) or 1.0
            vectors.append([v / norm for v in vec])
        return vectors


class TextLoader(Loader):
    def load(self, source_id: str, raw: str) -> Document:
        return Document(source_id, raw.strip(), {"source": source_id, "format": "text"})


class HTMLLoader(Loader):
    def load(self, source_id: str, raw: str) -> Document:
        text = re.sub(r"<(script|style)\b.*?</\1>", " ", raw, flags=re.S | re.I)
        text = re.sub(r"<[^>]+>", " ", text)
        text = " ".join(html.unescape(text).split())
        return Document(source_id, text, {"source": source_id, "format": "html"})


class PDFLoader(Loader):
    """Pages separated by form feeds (\f) in this exercise."""

    def load(self, source_id: str, raw: str) -> Document:
        pages = [page.strip() for page in raw.split("\f")]
        return Document(source_id, "\n".join(pages), {"source": source_id, "format": "pdf", "pages": len(pages)})


class LoaderFactory:
    def __init__(self) -> None:
        self._loaders: dict[str, type[Loader]] = {}

    @classmethod
    def default(cls) -> "LoaderFactory":
        factory = cls()
        for ext, loader in ((".txt", TextLoader), (".md", TextLoader), (".html", HTMLLoader),
                            (".htm", HTMLLoader), (".pdf", PDFLoader)):
            factory.register(ext, loader)
        return factory

    def register(self, extension: str, loader_cls: type[Loader]) -> None:
        ext = extension.lower()
        self._loaders[ext if ext.startswith(".") else "." + ext] = loader_cls

    def create(self, source_id: str) -> Loader:
        name = source_id.rsplit("/", 1)[-1]
        ext = "." + name.rsplit(".", 1)[-1].lower() if "." in name else ""
        if ext not in self._loaders:
            raise UnsupportedFormat(f"no loader for {source_id!r}")
        return self._loaders[ext]()


class FixedSizeChunker(Chunker):
    def __init__(self, size: int, overlap: int = 0) -> None:
        if size <= 0 or overlap < 0 or overlap >= size:
            raise ValueError("need size > 0 and 0 <= overlap < size")
        self.size = size
        self.overlap = overlap

    def chunk(self, doc: Document) -> list[Chunk]:
        words = doc.text.split()
        chunks: list[Chunk] = []
        step = self.size - self.overlap
        for start in range(0, len(words), step):
            piece = words[start:start + self.size]
            chunks.append(Chunk(doc.id, len(chunks), " ".join(piece), dict(doc.metadata)))
            if start + self.size >= len(words):
                break
        return chunks


class InMemoryVectorStore(VectorStore):
    def __init__(self) -> None:
        self._items: list[tuple[Chunk, list[float]]] = []

    def add(self, chunks: list[Chunk], vectors: list[list[float]]) -> None:
        if len(chunks) != len(vectors):
            raise ValueError("chunks and vectors must have the same length")
        self._items.extend(zip(chunks, vectors))

    @staticmethod
    def _cosine(a: list[float], b: list[float]) -> float:
        na = math.sqrt(sum(x * x for x in a))
        nb = math.sqrt(sum(x * x for x in b))
        return sum(x * y for x, y in zip(a, b)) / (na * nb) if na and nb else 0.0

    def search(self, vector: list[float], k: int) -> list[Chunk]:
        ranked = sorted(self._items, key=lambda item: self._cosine(vector, item[1]), reverse=True)
        return [chunk for chunk, _ in ranked[:k]]

    def __len__(self) -> int:
        return len(self._items)


class IngestionPipeline:
    def __init__(self, factory: LoaderFactory, chunker: Chunker, embedder: Embedder, store: VectorStore) -> None:
        self.factory = factory
        self.chunker = chunker
        self.embedder = embedder
        self.store = store

    def ingest(self, source_id: str, raw: str) -> int:
        doc = self.factory.create(source_id).load(source_id, raw)
        chunks = self.chunker.chunk(doc)
        if not chunks:
            return 0
        self.store.add(chunks, self.embedder.embed([c.text for c in chunks]))
        return len(chunks)

    def search(self, query: str, k: int = 3) -> list[Chunk]:
        return self.store.search(self.embedder.embed([query])[0], k)
